471: float SimulatedSpectrumSource::nextUnitNoise() noexcept
472: {
473:     // Two independent uniforms form a zero-mean triangular distribution. sqrt(6)
474:     // normalizes it to unit variance, which is sufficient for realistic display
475:     // noise while making 16k/65k stress streams substantially faster.
