25:     static inline std::uint8_t mapToColorIndex(float amplitude,
26:                                                float referenceLevel,
27:                                                float bottomLevel) noexcept
28:     {
29:         if (!std::isfinite(amplitude)) {
30:             return 0U;
31:         }
32:         if (referenceLevel <= bottomLevel) {
33:             return amplitude >= referenceLevel ? 255U : 0U;
34:         }
35:         const float normalized = (amplitude - bottomLevel) / (referenceLevel - bottomLevel);
36:         const float scaled = normalized * 255.0F;
37:         const int clamped = std::clamp(static_cast<int>(std::floor(scaled)), 0, 255);
38:         return static_cast<std::uint8_t>(clamped);
39:     }
40: };
