552: bool SpectrumPlotWidget::isPeak(const std::size_t bin) const noexcept
553: {
554:     if (!frame_ || bin >= frame_->bins.size()) {
555:         return false;
556:     }
557:     const float value = frame_->bins[bin];
558:     if (!std::isfinite(value) || value < peakThreshold_) {
559:         return false;
560:     }
561:     const bool notBelowLeft = bin == 0U
562:         || !std::isfinite(frame_->bins[bin - 1U])
563:         || value >= frame_->bins[bin - 1U];
564:     const bool notBelowRight = bin + 1U >= frame_->bins.size()
565:         || !std::isfinite(frame_->bins[bin + 1U])
566:         || value >= frame_->bins[bin + 1U];
567:     const bool strictlyAboveNeighbor = (bin > 0U
568:         && std::isfinite(frame_->bins[bin - 1U])
569:         && value > frame_->bins[bin - 1U])
570:         || (bin + 1U < frame_->bins.size()
571:             && std::isfinite(frame_->bins[bin + 1U])
572:             && value > frame_->bins[bin + 1U]);
573:     return notBelowLeft && notBelowRight && strictlyAboveNeighbor;
574: }
