void SpectrumPlotWidget::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() != Qt::LeftButton || !leftButtonPressed_) {
        QWidget::mouseReleaseEvent(event);
        return;
    }
    const bool wasBoxZooming = boxZooming_;
    leftButtonPressed_ = false;
    panning_ = false;
    boxZooming_ = false;
    unsetCursor();
    if (zoomBand_) {
        zoomBand_->hide();
