112: 
113:     QImage newImage(newWidth, newHeight, QImage::Format_Indexed8);
114:     newImage.setColorTable(colorTable_);
115:     newImage.fill(0);
116: 
117:     if (!bufferImage_.isNull() && rowCount_ > 0) {
118:         // Preserve existing history into new image buffer
119:         QPainter p(&newImage);
120:         if (rowCount_ < historyDepth_) {
121:             const int h = std::min(rowCount_, newHeight);
122:             const QRect src(0, headRow_, bufferWidth_, h);
123:             const QRect dst(0, newHeight - h, newWidth, h);
124:             p.drawImage(dst, bufferImage_, src);
125:             headRow_ = newHeight - h;
126:         } else {
127:             const int h1 = std::min(historyDepth_ - headRow_, newHeight);
128:             const QRect src1(0, headRow_, bufferWidth_, h1);
129:             const QRect dst1(0, 0, newWidth, h1);
130:             p.drawImage(dst1, bufferImage_, src1);
131: 
132:             const int h2 = std::min(headRow_, newHeight - h1);
133:             if (h2 > 0) {
134:                 const QRect src2(0, 0, bufferWidth_, h2);
135:                 const QRect dst2(0, h1, newWidth, h2);
136:                 p.drawImage(dst2, bufferImage_, src2);
137:             }
138:             headRow_ = 0;
139:         }
140:         p.end();
141:         rowCount_ = std::min(rowCount_, newHeight);
142:     } else {
143:         headRow_ = 0;
144:         rowCount_ = 0;
145:     }
146: 
147:     bufferWidth_ = newWidth;
