13: /**
14:  * @brief 工业级焦点门控滚轮事件过滤器 (Focus-Gated Wheel Event Filter)
15:  *
16:  * 解决在包含大量输入控件的滚动面板中，鼠标上下滑动误触修改控件数值的问题。
17:  * - 未获得焦点的输入控件（!hasFocus()）忽略滚轮事件，让事件自然冒泡至父级 QScrollArea 实现页面滚动；
18:  * - 只有用户显式点击获取焦点（hasFocus() == true）后，才允许滚轮调节控件数值。
19:  */
20: class UnfocusedWheelFilter final : public QObject {
21: public:
22:     explicit UnfocusedWheelFilter(QObject* parent = nullptr)
23:         : QObject(parent)
24:     {
25:     }
26: 
27:     static void installRecursively(QWidget* root)
28:     {
29:         if (!root) {
30:             return;
31:         }
32:         auto* filter = new UnfocusedWheelFilter(root);
33:         applyFilter(root, filter);
34:     }
35: 
36: protected:
37:     bool eventFilter(QObject* watched, QEvent* event) override
38:     {
39:         if (event->type() == QEvent::Wheel) {
40:             auto* widget = qobject_cast<QWidget*>(watched);
41:             if (widget && !widget->hasFocus()) {
42:                 event->ignore();
43:                 return true;
44:             }
45:         }
46:         return QObject::eventFilter(watched, event);
47:     }
48: 
49: private:
50:     static void applyFilter(QWidget* root, UnfocusedWheelFilter* filter)
51:     {
52:         for (auto* child : root->findChildren<QWidget*>()) {
53:             if (qobject_cast<QAbstractSpinBox*>(child)
54:                 || qobject_cast<QComboBox*>(child)
55:                 || qobject_cast<QSlider*>(child)) {
56:                 child->setFocusPolicy(Qt::StrongFocus);
57:                 child->installEventFilter(filter);
58:             }
59:         }
60:     }
61: };
